      <article class="tool-card"><div class="icon">#</div><h3>3. URL Slug Generator</h3><label for="slug-input">Page or post title</label><input id="slug-input" type="text" placeholder="e.g. My New Website" style="width:100%;margin:.5rem 0;padding:.7rem"><p id="slug-result" class="tool-result" aria-live="polite">my-new-website</p><button class="button primary" type="button" id="slug-copy">Copy slug</button></article>
      <article class="tool-card"><div class="icon">🔐</div><h3>4. Password Generator</h3><label for="pw-length">Length: <strong id="pw-length-label">16</strong></label><input id="pw-length" type="range" min="8" max="48" value="16" style="width:100%"><label><input id="pw-symbols" type="checkbox" checked> Include symbols</label><p id="pw-result" class="tool-result" aria-live="polite">Click Generate</p><button class="button primary" type="button" id="pw-generate">Generate password</button> <button class="button secondary" type="button" id="pw-copy">Copy</button></article>
      <article class="tool-card"><div class="icon">%</div><h3>5. Percentage Calculator</h3><label for="pct-rate">What percent?</label><input id="pct-rate" type="number" min="0" step="any" placeholder="e.g. 15" style="width:100%;padding:.7rem;margin:.35rem 0"><label for="pct-base">Of this number</label><input id="pct-base" type="number" step="any" placeholder="e.g. 2000" style="width:100%;padding:.7rem;margin:.35rem 0"><p class="tool-result" id="pct-result" aria-live="polite">Result: —</p><button class="button primary" type="button" id="pct-calc">Calculate</button></article>
