      <article class="tool-card"><div class="icon">📈</div><h3>7. Profit Margin Calculator</h3><label for="profit-cost">Cost (Rs)</label><input id="profit-cost" type="number" min="0" step="any" placeholder="Cost" style="width:100%;padding:.7rem;margin:.35rem 0"><label for="profit-sale">Selling price (Rs)</label><input id="profit-sale" type="number" min="0" step="any" placeholder="Selling price" style="width:100%;padding:.7rem;margin:.35rem 0"><p class="tool-result" id="profit-result" aria-live="polite">Profit: —</p><button class="button primary" type="button" id="profit-calc">Calculate profit</button></article>
