<script>
(function(){
 const $=id=>document.getElementById(id);
 const num=id=>Number.parseFloat($(id).value);
 const fmt=n=>Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:2}):'—';
 const copy=async value=>{try{await navigator.clipboard.writeText(value)}catch(e){const t=document.createElement('textarea');t.value=value;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove()}};
 $('tool-text').addEventListener('input',()=>{const t=$('tool-text').value.trim();$('tool-words').textContent=t?t.split(/\s+/).length:0;$('tool-chars').textContent=$('tool-text').value.length;$('tool-nospace').textContent=$('tool-text').value.replace(/\s/g,'').length});
 document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>{const t=$('case-text').value;let out=t;if(b.dataset.case==='upper')out=t.toUpperCase();if(b.dataset.case==='lower')out=t.toLowerCase();if(b.dataset.case==='title')out=t.toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());if(b.dataset.case==='sentence')out=t.toLowerCase().replace(/(^\s*\w|[.!?]\s+\w)/g,c=>c.toUpperCase());$('case-result').textContent=out}));
 const slug=()=> $('slug-result').textContent=$('slug-input').value.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
 $('slug-input').addEventListener('input',slug);$('slug-copy').addEventListener('click',()=>copy($('slug-result').textContent));
 $('pw-length').addEventListener('input',()=> $('pw-length-label').textContent=$('pw-length').value);
 $('pw-generate').addEventListener('click',()=>{let chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';if($('pw-symbols').checked)chars+='!@#$%^&*()-_=+';let out='';for(let i=0;i<Number($('pw-length').value);i++)out+=chars[crypto.getRandomValues(new Uint32Array(1))[0]%chars.length];$('pw-result').textContent=out});
 $('pw-copy').addEventListener('click',()=>copy($('pw-result').textContent));
 $('pct-calc').addEventListener('click',()=> $('pct-result').textContent='Result: '+fmt(num('pct-rate')*num('pct-base')/100));
 $('disc-calc').addEventListener('click',()=>{let p=num('disc-price'),r=num('disc-rate');if(p<0||r<0||r>100)return $('disc-result').textContent='Enter a valid price and 0–100% discount.';$('disc-result').textContent='Savings: Rs '+fmt(p*r/100)+' · Pay: Rs '+fmt(p*(1-r/100))});
 $('profit-calc').addEventListener('click',()=>{let c=num('profit-cost'),s=num('profit-sale');if(c<0||s<0||s===0)return $('profit-result').textContent='Enter valid non-negative values and a selling price above zero.';let p=s-c;$('profit-result').textContent=(p>=0?'Profit: ':'Loss: ')+'Rs '+fmt(Math.abs(p))+' · Margin: '+fmt(p/s*100)+'%'});
 $('gst-calc').addEventListener('click',()=>{let a=num('gst-amount'),r=num('gst-rate');if(a<0||r<0||r>100)return $('gst-result').textContent='Enter valid non-negative values and a tax rate from 0–100%.';$('gst-result').textContent='Tax: Rs '+fmt(a*r/100)+' · Total: Rs '+fmt(a*(1+r/100))});
 const convert=()=>{let v=num('unit-value'),type=$('unit-type').value,formula={kg:n=>n*2.2046226218,lb:n=>n/2.2046226218,km:n=>n*0.6213711922,mi:n=>n/0.6213711922,c:n=>n*9/5+32,f:n=>(n-32)*5/9}[type];let label={kg:'lb',lb:'kg',km:'mi',mi:'km',c:'°F',f:'°C'}[type];$('unit-result').textContent=fmt(v)+' → '+fmt(formula(v))+' '+label};
 $('unit-value').addEventListener('input',convert);$('unit-type').addEventListener('change',convert);
 $('age-calc').addEventListener('click',()=>{let value=$('birth-date').value;if(!value)return $('age-result').textContent='Please select a date.';let dob=new Date(value+'T00:00:00'),now=new Date();if(dob>now)return $('age-result').textContent='Date of birth cannot be in the future.';let years=now.getFullYear()-dob.getFullYear(),months=now.getMonth()-dob.getMonth(),days=now.getDate()-dob.getDate();if(days<0){months--;days+=new Date(now.getFullYear(),now.getMonth(),0).getDate()}if(months<0){years--;months+=12}$('age-result').textContent=years+' years, '+months+' months, '+days+' days'});
 slug();convert();
})();
</script>
@endsection
